import{_ as s,l,o as a,c as n,v as t,p as i,x as o,d as p,i as S,S as d}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"NewSQL","description":"","frontmatter":{"title":"NewSQL","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/newsql.md","filePath":"cs/newsql.md","lastUpdated":1789023840000}'),c={name:"cs/newsql.md"};function h(_,e,L,A,m,E){const r=l("Mermaid");return a(),n("div",null,[e[1]||(e[1]=t('<h1 id="newsql" tabindex="-1">NewSQL <a class="header-anchor" href="#newsql" aria-label="Permalink to &quot;NewSQL&quot;">​</a></h1><div class="epigraph"><p>NewSQL 标签：关系 SQL、跨分片事务、水平扩展。实现仍在 2PC、Calvin、Spanner 路线里选，不是第三种代数。</p><footer>—— 据 Pavlo and Aslett NewSQL 综述；Stonebraker；本课前面的协议拼图</footer></div><p><a href="/cs/htap">上一课</a>给了双引擎。本课给产品族名字：NoSQL 放弃 SQL 与多行事务换扩展；NewSQL 想把 SQL 事务拿回来仍分片。分布式数据库序列封口。缺口是分类，避免把商标当新理论。数据模型族从 RocksDB 再开节点内引擎。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>定义松：Google Spanner、Cockroach、TiDB、VoltDB 等被归入。共同承诺：SQL、ACID（或外部一致）、自动分片。分歧：时钟 vs 定序 vs 单分区无跨片。缺口是<strong>用已学协议读白皮书</strong>：有无 TrueTime、是否确定性、存储 LSM 还是缓冲池 B+、是否存算分离。</p><p>不是「比 Postgres 快」的同义词。单机 Postgres 仍可更快；NewSQL 买的是故障域与扩展。</p><p><span class="marginnote">Pavlo and Aslett 对 NewSQL 的整理。Stonebraker 对 NoSQL 的批评（「One Size Fits None」脉络）。本课不排名。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读一家系统：① 分片键与再平衡；② 跨片协议（2PC/Calvin/时钟）；③ 日志粒度与 CDC；④ 隔离实际是 SI 还是 SSI；⑤ 存储引擎。对照本课程树。</p><p>基准用 TPC-C 跨分片比例，后课。Jepsen 测声称的一致。</p>',10)),(a(),i(d,null,{default:o(()=>[S(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20SQL%5B%22SQL%20%2B%20%E4%BC%98%E5%8C%96%E5%99%A8%22%5D%20--%3E%20SH%5B%22%E8%87%AA%E5%8A%A8%E5%88%86%E7%89%87%22%5D%0A%20%20SH%20--%3E%20TX%5B%22%E8%B7%A8%E7%89%87%E4%BA%8B%E5%8A%A1%E5%8D%8F%E8%AE%AE%22%5D%0A%20%20TX%20--%3E%20STO%5B%22LSM%20%E6%88%96%E9%A1%B5%E7%BC%93%E5%AD%98%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>优化器：必须分片裁剪与 broadcast/shuffle。没有则 SQL 是一层慢的 scatter。ORM 阻抗在分布式下 N+1 变成 N×分片。连接池对着网关。</p><p>HTAP 功能常当附件（列副本），不是 NewSQL 定义的一部分。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 RocksDB 内部 compaction——下一课。也不把 NewSQL 当图数据库。文档库宽列各开课。</p><p>后课默认：见到 NewSQL 用协议清单拆解。RocksDB：嵌入式 LSM，常当 NewSQL 的本地引擎。</p><p>标签不增加定理。协议已经在前面课里。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>NewSQL = SQL + 分片 + 分布式事务，实现路线已知。</li><li>用分片、协议、存储、隔离四问读系统。</li><li>下一序列 RocksDB：节点内 LSM 引擎。</li><li>出处：Pavlo and Aslett；Stonebraker；Spanner/Calvin 对照。</li></ul>',9))])}const Q=s(c,[["render",h]]);export{u as __pageData,Q as default};
